-- 3. Link to Nouns category

    INSERT INTO public.word_categories (word_id, category_id)
    SELECT w.id, '4a9d2566-a9fe-422a-b710-cf0324d758a2'::uuid
    FROM public.words w
    WHERE w.part_of_speech = 'noun'
    ON CONFLICT (word_id, category_id) DO NOTHING;
    
-- 4. Insert word_meanings

    DELETE FROM public.word_meanings
    WHERE word_id IN (SELECT id FROM public.words WHERE part_of_speech = 'noun');
    

    INSERT INTO public.word_meanings (
        word_id, translation, accepted_translations, definition, example_en, example_bg, sort_order
    ) VALUES 
((SELECT id FROM public.words WHERE normalized_headword = 'time' AND part_of_speech = 'noun'), 'време', ARRAY[]::text[], NULL, 'I don''t have time today.', 'Днес нямам време.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'time' AND part_of_speech = 'noun'), 'път', ARRAY['пъти']::text[], NULL, 'This is my third time here.', 'Това е третият ми път тук.', 1),
((SELECT id FROM public.words WHERE normalized_headword = 'thing' AND part_of_speech = 'noun'), 'нещо', ARRAY['вещ','работа']::text[], NULL, 'What is that thing on the shelf?', 'Какво е онова нещо на рафта?', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'way' AND part_of_speech = 'noun'), 'начин', ARRAY[]::text[], NULL, 'There is a better way to do this.', 'Има по-добър начин да се направи това.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'way' AND part_of_speech = 'noun'), 'посока', ARRAY['път']::text[], NULL, 'Which way is the station?', 'В коя посока е гарата?', 1),
((SELECT id FROM public.words WHERE normalized_headword = 'part' AND part_of_speech = 'noun'), 'част', ARRAY[]::text[], NULL, 'The first part of the film is slow.', 'Първата част на филма е бавна.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'place' AND part_of_speech = 'noun'), 'място', ARRAY[]::text[], NULL, 'Is this place taken?', 'Това място заето ли е?', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'try' AND part_of_speech = 'noun'), 'опит', ARRAY[]::text[], NULL, 'Give it another try.', 'Опитай още веднъж.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'kind' AND part_of_speech = 'noun'), 'вид', ARRAY['род','сорт']::text[], NULL, 'This kind of bird lives near water.', 'Този вид птица живее близо до вода.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'side' AND part_of_speech = 'noun'), 'страна', ARRAY[]::text[], NULL, 'Walk on the right side of the road.', 'Върви по дясната страна на пътя.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'half' AND part_of_speech = 'noun'), 'половина', ARRAY[]::text[], NULL, 'Half of the class was absent.', 'Половината клас отсъстваше.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'work' AND part_of_speech = 'noun'), 'работа', ARRAY['труд']::text[], NULL, 'She does important work.', 'Тя върши важна работа.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'moment' AND part_of_speech = 'noun'), 'момент', ARRAY['миг']::text[], NULL, 'Every moment with him is special.', 'Всеки момент с него е специален.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'reason' AND part_of_speech = 'noun'), 'причина', ARRAY[]::text[], NULL, 'What is the reason for the delay?', 'Каква е причината за забавянето?', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'name' AND part_of_speech = 'noun'), 'име', ARRAY[]::text[], NULL, 'Write your name on the form.', 'Напиши името си във формуляра.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'sort' AND part_of_speech = 'noun'), 'вид', ARRAY['сорт','разновидност']::text[], NULL, 'Apples of every sort are on sale.', 'Ябълки от всякакъв вид са на промоция.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'element' AND part_of_speech = 'noun'), 'елемент', ARRAY[]::text[], NULL, 'Trust is a key element of friendship.', 'Доверието е ключов елемент на приятелството.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'fact' AND part_of_speech = 'noun'), 'факт', ARRAY[]::text[], NULL, 'That is a well-known fact.', 'Това е добре известен факт.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'type' AND part_of_speech = 'noun'), 'тип', ARRAY['вид']::text[], NULL, 'He is not my type.', 'Той не е моят тип.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'result' AND part_of_speech = 'noun'), 'резултат', ARRAY[]::text[], NULL, 'The test results came back today.', 'Резултатите от теста дойдоха днес.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'point' AND part_of_speech = 'noun'), 'точка', ARRAY[]::text[], NULL, 'Mark the point on the map.', 'Отбележи точката на картата.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'point' AND part_of_speech = 'noun'), 'смисъл', ARRAY['цел','значение']::text[], NULL, 'There is no point in arguing.', 'Няма смисъл да спорим.', 1),
((SELECT id FROM public.words WHERE normalized_headword = 'view' AND part_of_speech = 'noun'), 'гледка', ARRAY[]::text[], NULL, 'The view from the balcony is lovely.', 'Гледката от балкона е прекрасна.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'view' AND part_of_speech = 'noun'), 'мнение', ARRAY['възглед','гледна точка']::text[], NULL, 'In my view the price is fair.', 'Според мен цената е справедлива.', 1),
((SELECT id FROM public.words WHERE normalized_headword = 'life' AND part_of_speech = 'noun'), 'живот', ARRAY[]::text[], NULL, 'Life in a small town is quiet.', 'Животът в малкото градче е спокоен.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'example' AND part_of_speech = 'noun'), 'пример', ARRAY[]::text[], NULL, 'This is a good example of teamwork.', 'Това е добър пример за работа в екип.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'question' AND part_of_speech = 'noun'), 'въпрос', ARRAY[]::text[], NULL, 'I have a question about homework.', 'Имам въпрос за домашното.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'problem' AND part_of_speech = 'noun'), 'проблем', ARRAY[]::text[], NULL, 'We solved the problem together.', 'Решихме проблема заедно.', 0),
((SELECT id FROM public.words WHERE normalized_headword = 'idea' AND part_of_speech = 'noun'), 'идея', ARRAY[]::text[], NULL, 'She came up with an idea.', 'Тя излезе с идея.', 0),
